package org.lwjgl.opengl;import java.util.*;public class GL11{public static final List<String> operations=new ArrayList<>();public static void glPushMatrix(){operations.add("push");}public static void glPopMatrix(){operations.add("pop");}public static void glTranslated(double x,double y,double z){operations.add("translate:"+x+","+y+","+z);}public static void glRotated(double angle,double x,double y,double z){operations.add("rotate:"+angle+","+x+","+y+","+z);}}
